#!/usr/bin/env python3
"""Generate the fixed DODO board pins; --check detects stale generated files."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "firmware/boards/dodo-s3-lcd/board.json"
HEADER = ROOT / "firmware/components/bsp_dodo_s3_lcd/private_include/board_generated.h"
KCONFIG = ROOT / "firmware/main/Kconfig.board"


def generate(check=False):
    board = json.loads(SOURCE.read_text())
    if board["schemaVersion"] != 1 or board["boardId"] != "dodo-s3-lcd":
        raise ValueError("unsupported board identity")
    lcd = board["display"]
    if (lcd["width"], lcd["height"]) != (240, 320):
        raise ValueError("DODO display must be 240x320")
    pins = [lcd[k] for k in ("mosi", "sclk", "cs", "dc", "reset", "backlight")]
    pins += [board["input"]["boot"], board["climate"]["dht11"]]
    joystick = board["input"]["joystick"]
    pins += [joystick[key] for key in ("x", "y", "select")]
    if any(type(joystick[key]) is not int or not 1 <= joystick[key] <= 10 for key in ("x", "y")):
        raise ValueError("joystick axes require ADC1 GPIOs")
    light = board["light"]["gpio"]
    if type(light) is not int or not 1 <= light <= 10:
        raise ValueError("light sensor requires an ADC1 GPIO")
    pins.append(light)
    audio = board["audio"]
    if any(type(audio[key]["i2s"]) is not int for key in ("mic", "speaker")) or \
            {audio["mic"]["i2s"], audio["speaker"]["i2s"]} != {0, 1}:
        raise ValueError("microphone and speaker require separate I2S ports")
    pins += [audio["mic"][k] for k in ("bclk", "ws", "din")]
    pins += [audio["speaker"][k] for k in ("bclk", "ws", "dout")]
    if any(type(p) is not int or not 0 <= p <= 48 for p in pins) or len(set(pins)) != len(pins):
        raise ValueError("invalid or overlapping GPIOs")
    # N16R8 memory, native USB, UART console, straps and either DevKitC-1 RGB revision.
    reserved = {3, 19, 20, 38, 43, 44, 45, 46, 48, *range(22, 38)}
    if any(p in reserved for p in pins) or board["input"]["boot"] != 0:
        raise ValueError("GPIO reserved by ESP32-S3-DevKitC-1 N16R8")
    values = {"LCD_" + k.upper(): v for k, v in lcd.items() if k != "invertColor"}
    values["LCD_INVERT_COLOR"] = int(lcd["invertColor"])
    values["BOOT_GPIO"] = board["input"]["boot"]
    values["DHT11_GPIO"] = board["climate"]["dht11"]
    values.update({"JOYSTICK_" + key.upper(): value for key, value in joystick.items()})
    values["LIGHT_GPIO"] = light
    for device in ("mic", "speaker"):
        values.update({f"{device.upper()}_{key.upper()}": value for key, value in audio[device].items()})
    header = "/* Generated by tools/board_codegen.py; do not edit. */\n#pragma once\n\n"
    header += "".join(f"#define PET_BOARD_{k} {v}\n" for k, v in values.items())
    kconfig = "# Generated by tools/board_codegen.py; do not edit.\n"
    kconfig += f"config PET_BOARD_DHT11_GPIO\n    int\n    default {values['DHT11_GPIO']}\n"
    for path, content in ((HEADER, header), (KCONFIG, kconfig)):
        if check:
            if not path.exists() or path.read_text() != content:
                raise ValueError(f"stale generated file: {path.relative_to(ROOT)}")
        else:
            path.write_text(content)
    print("OK: board pins and generated files")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    generate(parser.parse_args().check)
